SourceCode.Declaration:
public class METCustomerMDFPosting_SalesInvoice extends METCustomerMDFPosting
{
    MetShipmentId shipmentId;
    SalesTable salesTable;

}

Method.Source:
public MetShipmentId parmShipmentId(MetShipmentId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;

    return shipmentId;
}

Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(METCustomerMDFConsolidationTable));
    qbds.addRange(fieldNum(METCustomerMDFConsolidationTable, ShipmentId)).value(queryValue(shipmentId));

    return ret;
}

final void post()
{
    // No implementation needed as autoPost returns false
}

RecId createMarkupTrans(METCustomerMDFConsolidationTable _consolidationPosting)
{
    MarkupTrans markupTrans;
    MetCustomerMdfSetupTable customerMDFSetupTable;
    MarkupTable markupTable;

    customerMDFSetupTable = MetCustomerMdfSetupTable::findRecId(_consolidationPosting.CustomerMDFSetupTable);
    //todo: configuration for the delivery markup fee
    markupTable = MarkupTable::find(MarkupModuleType::Cust,"Delivery");

    markupTrans.clear();
    markupTrans.TransTableId    = salesTable.TableId;
    markupTrans.TransRecId      = salesTable.RecId;
    markupTrans.initValue();    // initValue call must be after transTableId and transRecId are populated
    markupTrans.initFromMarkupTable(markupTable);
    markupTrans.initFromSalesTable(salesTable);
    markupTrans.MarkupCode      = markupTable.MarkupCode;
    markupTrans.ModuleCategory  = HeadingLine::Heading;
    markupTrans.ModuleType      = MarkupModuleType::Cust;
    markupTrans.MarkupCategory  = MarkupCategory::Fixed;
    markupTrans.CurrencyCode    = salesTable.CurrencyCode; // The MarkupTrans record must have the same currency as the sales order
    markupTrans.Value           = _consolidationPosting.MDF;


    if(markupTrans.validateWrite())
    {
        markupTrans.insert();
    }

    return markupTrans.RecId;
}

SalesTable findSalesTableHeader(METCustomerMDFConsolidationTable _consolidationPosting)
{        
    SalesTable salesTableSelect;
    METSalesOrderShipmentLoadLines shipmentLoadLines;

    select firstonly salesTableSelect
        order by CreatedDateTime desc
        exists join shipmentLoadLines
        where salesTableSelect.SalesId == shipmentLoadLines.OrderNum
           && shipmentLoadLines.ShipmentId == _consolidationPosting.ShipmentId;

    return salesTableSelect;
}

void updateCustomerMDFConsolidationTable(METCustomerMDFConsolidationTable _consolidationPosting, RefRecId _postingRefRecId)
{
    METCustomerMDFConsolidationTable consolidationTableUpdate;

    update_recordset consolidationTableUpdate
        setting PostingRefTableId = this.getPostingTableId(),
                PostingRefRecId = _consolidationPosting.PostingRefRecId
        where consolidationTableUpdate.CustAccount == _consolidationPosting.CustAccount
           && consolidationTableUpdate.ShipmentId == _consolidationPosting.ShipmentId
           && consolidationTableUpdate.CustomerMDFSetupTable == _consolidationPosting.CustomerMDFSetupTable
           && consolidationTableUpdate.PostingRefRecId == 0;
}
